#!/usr/bin/env node
/**
 * PreToolUse hook: refuse edits to generated files.
 *
 * `src/data/artists.generated.ts` is produced by
 * `yarn generate:bandcamp-artists`. Hand-edits are silently lost on the next
 * regeneration, so this blocks the write rather than relying on an agent
 * honouring the instruction in AGENTS.md.
 *
 * Fails open: any unexpected payload or error allows the tool through, so a
 * schema change in the host can never wedge a session.
 */

const PROTECTED_PATTERNS = [/src[/\\]data[/\\]artists\.generated\.ts$/i];

const WRITE_TOOL =
  /^(edit|create|write|apply_?patch|str_?replace\w*|multi_?edit|notebook_?edit)$/i;
const SHELL_TOOL = /^(bash|shell|run_in_terminal|execute_command)$/i;

// Shell constructs that would modify a file in place.
const SHELL_MUTATION = /(>>?|\btee\b|\bsed\s+-i\b|\btruncate\b|\bcp\b|\bmv\b|\brm\b)/;

function readStdin() {
  return new Promise((resolve) => {
    let data = "";
    const timer = setTimeout(() => resolve(data), 4000);
    process.stdin.setEncoding("utf8");
    process.stdin.on("data", (chunk) => (data += chunk));
    process.stdin.on("end", () => {
      clearTimeout(timer);
      resolve(data);
    });
    process.stdin.on("error", () => {
      clearTimeout(timer);
      resolve("");
    });
  });
}

function isProtected(value) {
  if (typeof value !== "string" || !value) return false;
  const normalized = value.split("?")[0].replace(/^file:\/\//, "");
  return PROTECTED_PATTERNS.some((pattern) => pattern.test(normalized));
}

function deny(reason) {
  process.stdout.write(
    JSON.stringify({
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        permissionDecision: "deny",
        permissionDecisionReason: reason,
      },
    })
  );
  process.exit(0);
}

const REASON =
  "src/data/artists.generated.ts is generated by `yarn generate:bandcamp-artists`. " +
  "Hand-edits are overwritten on the next run. Change scripts/update-bandcamp-artists.mjs " +
  "or the normalization helpers in src/lib/artists.ts instead.";

async function main() {
  const raw = await readStdin();
  if (!raw.trim()) process.exit(0);

  let payload;
  try {
    payload = JSON.parse(raw);
  } catch {
    process.exit(0); // fail open
  }

  const toolName = String(
    payload.tool_name ?? payload.toolName ?? payload.name ?? ""
  );
  const input =
    payload.tool_input ?? payload.toolInput ?? payload.arguments ?? {};

  if (!toolName || typeof input !== "object" || input === null) {
    process.exit(0);
  }

  if (WRITE_TOOL.test(toolName)) {
    const targets = [
      input.file_path,
      input.filePath,
      input.path,
      input.uri,
      input.target_file,
      input.notebook_path,
    ];
    if (targets.some(isProtected)) deny(REASON);
  }

  if (SHELL_TOOL.test(toolName)) {
    const command = String(input.command ?? input.cmd ?? "");
    const mentioned = command.match(/\S*artists\.generated\.ts/)?.[0] ?? "";
    if (isProtected(mentioned) && SHELL_MUTATION.test(command)) {
      deny(REASON);
    }
  }

  process.exit(0);
}

main().catch(() => process.exit(0));
